m=Chem.AddHs(Chem.MolFromSmiles('n1ccccc1C(C([O-])(c2ccccc2)C(F)(F)F)N=C(Nc2c(C)cccc2C)C'))
bonds={tuple(sorted((b.GetBeginAtomIdx(),b.GetEndAtomIdx()))) for b in m.GetBonds()}
# metal-coordination plus Cp ring/methyl bond indices
bonds|={tuple(sorted((54,i))) for i in [0,8,19,55,56,57,58,59]}
for i in range(55,60): bonds.add(tuple(sorted((i,60+(i-55)*4))))
